<?php require 'includes/bootstrap.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']);$app=trim($_POST['application_no']);$email=trim($_POST['email']);$phone=trim($_POST['phone']);$college=trim($_POST['college']);$branch=trim($_POST['branch']);$year=(int)$_POST['study_year'];$pw=$_POST['password']; try{$s=$pdo->prepare('INSERT INTO students(name,application_no,email,phone,college,branch,study_year,password_hash) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$name,$app,$email,$phone?:null,$college,$branch,$year,password_hash($pw,PASSWORD_DEFAULT)]);flash('success','Account created. Please log in.');redirect('login.php');}catch(PDOException $e){flash('error','Email or application number already exists.');}}
$title='Student Registration';$base='';$nav='<a href="login.php">Login</a>';include 'includes/header.php';?><div class="card form"><h2>Create student account</h2><form method="post"><label>Name</label><input name="name" required><label>Application No.</label><input name="application_no" required><label>Email</label><input type="email" name="email" required><label>Phone</label><input name="phone"><label>College</label><input name="college" required><label>Branch</label><input name="branch" required><label>Study Year</label><input type="number" min="1" max="8" name="study_year" required><label>Password</label><input type="password" minlength="6" name="password" required><div class="actions"><button class="btn">Register</button></div></form></div><?php include 'includes/footer.php';?>
